// Regression test for: Cart total not updated when an item quantity is set to 0
// Generated by WebProbe gen-tests from 2026-11-11T19-24-45-357Z, report #5.
// It failed with the bug and passed on the clean site. Edit freely; promote-tests won't overwrite it.

import { test, expect } from "@playwright/test";

test("cart total drops the item when its quantity is set to 0", async ({ page }) => {
  const pageErrors: Error[] = [];
  page.on("pageerror", (err) => pageErrors.push(err));

  // Build the cart through the UI: one mug and one notebook.
  await page.goto("/product/mug");
  await page.getByRole("button", { name: "Add to cart" }).click();
  await page.goto("/product/notebook");
  await page.getByRole("button", { name: "Add to cart" }).click();

  await page.goto("/cart");
  const mugQty = page.getByRole("spinbutton", { name: "Quantity of Ceramic Mug" });
  await expect(mugQty).toBeVisible();

  // Raise the mug quantity, then set it to 0.
  await mugQty.fill("5");
  await expect(page.getByRole("heading", { name: "Total: $79.00" })).toBeVisible();
  await mugQty.fill("0");

  // Only the notebook ($9) should remain in the total.
  await expect(page.getByRole("heading", { name: "Total: $9.00", exact: true })).toBeVisible();

  // The mug is either removed from the cart or shown with quantity 0.
  if ((await mugQty.count()) > 0) {
    await expect(mugQty).toHaveValue("0");
  }

  expect(pageErrors).toEqual([]);
});
